package org.brightstats.stats;
import java.util.*;import java.nio.file.*;import com.google.gson.*;
public final class ExtendedLatentChecks {
 static int checks;static void require(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
 static LatentInteractionSem.Model model(int predictors){List<LatentInteractionSem.Factor> factors=new ArrayList<>();for(int j=0;j<predictors;j++)factors.add(new LatentInteractionSem.Factor("Predictor "+(j+1),new int[]{3*j,3*j+1,3*j+2}));return new LatentInteractionSem.Model(factors,new LatentInteractionSem.Factor("Outcome",new int[]{3*predictors,3*predictors+1,3*predictors+2}),List.of(new LatentInteractionSem.Interaction(0,predictors==1?0:1)));}
 static JsonObject record(double[][] data,LatentInteractionSem.Model model,LatentInteractionSem.Options options,LatentInteractionSem.NumericalProbe probe){var gson=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().create();JsonObject value=new JsonObject();value.add("data",gson.toJsonTree(data));value.add("model",gson.toJsonTree(model));value.add("options",gson.toJsonTree(options));value.add("probe",gson.toJsonTree(probe));value.add("implied",gson.toJsonTree(LatentInteractionSem.impliedMoments(data,model,options,probe.parameters())));return value;}
 public static void main(String[] args)throws Exception{Path out=Path.of(args[0]);Files.createDirectories(out);Random rng=new Random(991572);double[][] normal=new double[100][15];for(var row:normal){double[] x=new double[5];double common=.3*rng.nextGaussian();for(int j=0;j<4;j++)x[j]=common+rng.nextGaussian();x[4]=.35*x[0]+.25*x[1]-.15*x[2]+.1*x[3]+.2*x[0]*x[1]+.7*rng.nextGaussian();for(int j=0;j<15;j++)row[j]=(1+.1*(j%3))*x[j/3]+.5*rng.nextGaussian();}var four=model(4);var normalOptions=new LatentInteractionSem.Options(15,23,400,1,2e-6,1e-10,.002,.95);var initial=LatentInteractionSem.probe(normal,four,normalOptions,null);double[] theta=initial.parameters();for(int j=0;j<initial.labels().size();j++)if(initial.labels().get(j).startsWith("Product:"))theta[j]=.15;var normalProbe=LatentInteractionSem.probe(normal,four,normalOptions,theta);require(normalProbe.dimensions()==1&&Double.isFinite(normalProbe.logLikelihood()),"Four-predictor nonlinear model uses exact analytic elimination where valid");
  double[][] heavy=new double[90][6];for(var row:heavy){double xi=rng.nextGaussian()*Math.sqrt(5/(2*GaussianImputation.gamma(3.5,rng))),eta=.3*xi+.2*xi*xi+.7*rng.nextGaussian();for(int j=0;j<6;j++)row[j]=(1+.1*(j%3))*(j<3?xi:eta)+.6*rng.nextGaussian();}var one=model(1);var studentOptions=new LatentInteractionSem.Options(23,33,400,1,2e-6,1e-10,.002,.95,LatentInteractionSem.PredictorDistribution.STUDENT_T,7);var studentInitial=LatentInteractionSem.probe(heavy,one,studentOptions,null);double[] point=studentInitial.parameters();for(int j=0;j<point.length;j++)if(studentInitial.labels().get(j).startsWith("Product:"))point[j]=.15;var studentProbe=LatentInteractionSem.probe(heavy,one,studentOptions,point);require(studentProbe.dimensions()==1&&Double.isFinite(studentProbe.logLikelihood()),"Student t prior-density identity supplies finite marginal likelihood");var refined=new LatentInteractionSem.Options(33,41,400,1,2e-6,1e-10,.002,.95,LatentInteractionSem.PredictorDistribution.STUDENT_T,7);var refinement=LatentInteractionSem.probe(heavy,one,refined,point);require(Math.abs(refinement.logLikelihood()-studentProbe.logLikelihood())<1e-5,"Independent node refinement at fixed Student parameters");
  var linear=new LatentInteractionSem.Model(one.predictors(),one.outcome(),List.of());require(LatentInteractionSem.probe(heavy,linear,studentOptions,null).dimensions()==1,"Student predictors do not receive invalid Gaussian analytic elimination");var legacy=new LatentInteractionSem.Options(15,23,500,2,2e-6,1e-10,.001,.95);require(legacy.predictorDistribution()==LatentInteractionSem.PredictorDistribution.NORMAL&&legacy.predictorDegreesOfFreedom()==7,"Legacy constructor remains Normal");try{new LatentInteractionSem.Options(15,23,500,2,2e-6,1e-10,.001,.95,LatentInteractionSem.PredictorDistribution.STUDENT_T,4);throw new AssertionError("Infinite quadratic variance allowed");}catch(IllegalArgumentException expected){checks++;}Thread.currentThread().interrupt();try{LatentInteractionSem.probe(heavy,one,studentOptions,point);throw new AssertionError("Extended quadrature cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
  var normalFit=LatentInteractionSem.fit(normal,four,normalOptions);var studentFit=LatentInteractionSem.fit(heavy,one,studentOptions);require(normalFit.converged()&&normalFit.integrationStable()&&normalFit.locallyIdentified()&&!normalFit.boundarySolution(),"Four-predictor full measurement/structural fit is regular");require(studentFit.converged()&&studentFit.integrationStable()&&studentFit.locallyIdentified()&&!studentFit.boundarySolution(),"Student-predictor full fit is regular");var gaussianBaseline=LatentInteractionSem.fit(heavy,linear,new LatentInteractionSem.Options(15,23,400,1,2e-6,1e-10,.002,.95));try{LatentInteractionSem.compare(gaussianBaseline,studentFit);throw new AssertionError("Mismatched predictor-distribution LR comparison accepted");}catch(IllegalArgumentException expected){checks++;}
  JsonObject result=new JsonObject();result.add("fourPredictor",record(normal,four,normalOptions,normalProbe));result.add("student",record(heavy,one,studentOptions,studentProbe));var gson=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().create();result.getAsJsonObject("fourPredictor").add("fit",gson.toJsonTree(normalFit));result.getAsJsonObject("student").add("fit",gson.toJsonTree(studentFit));result.addProperty("checks",checks);Files.writeString(out.resolve("cases.json"),new GsonBuilder().serializeSpecialFloatingPointValues().setPrettyPrinting().create().toJson(result));System.out.println("Extended latent checks: "+checks);
 }
}
